const { ethers } = require("ethers");
const colors = require("colors");
const cfonts = require("cfonts");

const displayHeader = require("../src/banner.js");
require("dotenv").config();
displayHeader();

const RPC_URL = "https://testnet-rpc.monad.xyz";
const EXPLORER_URL = "https://testnet.monadexplorer.com/tx/";
const CONTRACT_ADDRESS = "0xC995498c22a012353FAE7eCC701810D673E25794";

const provider = new ethers.providers.JsonRpcProvider(RPC_URL);

async function checkBalance(wallet) {
  const balance = await provider.getBalance(wallet.address);
  console.log(colors.cyan(`💰 Balance: ${ethers.utils.formatEther(balance)} ETH`));

  if (balance.lt(ethers.utils.parseEther("0.1"))) {
    console.error(colors.red("❌ Insufficient balance for transaction."));
    process.exit(1);
  }
}

async function sendTransaction(wallet) {
  await checkBalance(wallet);

  console.log(`🚀 Starting Monorail Module 🚀`.blue);
  console.log(colors.green(`✅ Wallet initialized: ${wallet.address}`));

  const walletData = { account: { address: wallet.address } };
  const data = `${walletData.account.address.replace(/^0x/, "")}`;

  const value = ethers.utils.parseEther("0.1");

  try {
    console.log(colors.yellow("🔍 Validating transaction..."));
    await provider.call({ to: CONTRACT_ADDRESS, data: data });
    console.log(colors.green("✅ Transaction is valid. Proceeding..."));

    let gasLimit;
    try {
      gasLimit = await provider.estimateGas({
        from: wallet.address,
        to: CONTRACT_ADDRESS,
        value: value,
        data: data,
      });
    } catch (err) {
      console.warn(colors.yellow("⚠️ Gas estimation failed. Using default gas limit."));
      gasLimit = ethers.utils.hexlify(500000);
    }

    const tx = {
      from: wallet.address,
      to: CONTRACT_ADDRESS,
      data: data,
      value: value,
      gasLimit: gasLimit,
      gasPrice: await provider.getGasPrice(),
    };

    console.log(colors.blue("🚀 Sending transaction..."));
    const txResponse = await wallet.sendTransaction(tx);
    console.log(colors.green(`✅ Transaction sent! Awaiting confirmation...`));
    await txResponse.wait();

    console.log(colors.green(`🎉 Transaction successful!`));
    console.log(colors.cyan(`🔗 Explorer: ${EXPLORER_URL}${txResponse.hash}`));
  } catch (error) {
    console.error(colors.red("❌ Transaction failed:", error.message || error));
  }
}

async function main() {
  const wallet = new ethers.Wallet(process.env.PRIVATE_KEY, provider);
  await sendTransaction(wallet);
}

main();